function readable(x,key=''){if(typeof x==='string'){if(['id','batch','interactive','filename','url'].includes(key)||/^s[0-9]-/.test(x))return x;return x.replace(/(RFC|UDP|TCP|TTL|VRID|VIP|protocol|priority|default|values|input|observed|group|MAC|because|exceeds|becomes|stays|at|by|than|only|both|same|with|Layer)([0-9])/gi,'$1 $2').replace(/IOSXE([0-9])/g,'IOS XE $1').replace(/IOS([0-9])/g,'IOS $1').replace(/([0-9])(?=to[0-9])/g,'$1 ').replace(/to(?=[0-9])/g,'to ').replace(/(HSRP|VRRP)v([123])/g,'$1 v$2').replace(/(Host)([12])/g,'$1 $2').replace(/only(?=IPv)/g,'only ');}if(Array.isArray(x))return x.map(a=>readable(a,key));if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,a])=>[readable(k),readable(a,k)]));return x;}
